// PROBE (temporary playtest harness — deleted before delivery).
// Runs the D1..D10 defect cases against TODAY's code. Brick collision is only
// reachable through frame(), so we drive it with a fake 2d context.
import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  frame,
  ballSpeed,
  WIDTH,
  PADDLE_Y,
  PADDLE_W,
  BALL_R,
} from '../game/neon.js';

// --- fake canvas context ------------------------------------------------
function fakeCtx() {
  return {
    fillStyle: '',
    font: '',
    globalCompositeOperation: '',
    globalAlpha: 1,
    fillRect() {},
    beginPath() {},
    arc() {},
    fill() {},
    fillText() {},
    drawImage() {},
  };
}

function baseState() {
  return {
    level: 1,
    lives: 3,
    score: 0,
    combo: 0,
    best: 0,
    paddle: { x: (WIDTH - PADDLE_W) / 2, y: PADDLE_Y, w: PADDLE_W, h: PADDLE_H },
    ball: { x: 320, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: 0, vy: 0 },
    bricks: [],
  };
}

const brick = (x, y, w = 72, h = 20) => ({ x, y, w, h, row: 0, alive: true, points: 50 });

// --- D1: no bounce at all on a brick --------------------------------------
test('D1: ball crossing the bottom face of a brick bounces (vy flips, vx untouched)', () => {
  const state = baseState();
  state.ball = { x: 136, y: 128, r: BALL_R, vx: 50, vy: -260 };
  state.bricks = [brick(100, 100)];
  step(state, 1 / 60); // ball now overlaps the brick
  frame(fakeCtx(), state);
  assert.equal(state.bricks[0].alive, false, 'brick must be destroyed');
  assert.ok(state.ball.vy > 0, 'vy must flip downward after hitting the bottom face');
  assert.equal(state.ball.vx, 50, 'vx must be untouched by a vertical hit');
});

// --- D2: tunneling through a brick at high speed ---------------------------
test('D2: level 6, dt=0.05 — a 35.5px step must still hit the brick', () => {
  const state = baseState();
  state.level = 6;
  state.ball = { x: 136, y: 127.1, r: BALL_R, vx: 0, vy: -ballSpeed(6) };
  state.bricks = [brick(100, 100)];
  step(state, 0.05); // crosses the whole 34px band in one step
  frame(fakeCtx(), state);
  assert.equal(state.bricks[0].alive, false, 'brick must be destroyed despite the long step');
  assert.ok(state.ball.vy > 0, 'ball must bounce off the brick');
});

// --- D3: seam straddle (gap 8 < diameter 14) -------------------------------
test('D3: ball straddling the 8px seam between two rows bounces exactly once', () => {
  const state = baseState();
  state.ball = { x: 40, y: 72, r: BALL_R, vx: 0, vy: 300 };
  state.bricks = [brick(4, 48), brick(4, 76)]; // rows 0 and 1 of the real grid
  assert.equal(collides(state.ball, state.bricks[0]), true, 'straddles row 0');
  assert.equal(collides(state.ball, state.bricks[1]), true, 'straddles row 1');
  frame(fakeCtx(), state);
  assert.ok(state.ball.vy < 0, 'vy must flip exactly once (not twice)');
  assert.equal(state.ball.y, 48 - BALL_R, 'ball pushed out above the seam');
  assert.ok(!collides(state.ball, state.bricks[0]), 'out of the upper brick');
  assert.ok(!collides(state.ball, state.bricks[1]), 'out of the lower brick');
  assert.equal(state.bricks[0].alive, false);
  assert.equal(state.bricks[1].alive, false);
});

// --- D4: face vs coin ------------------------------------------------------
test('D4a: side hit flips vx only and pushes the ball back out to the entry side', () => {
  const state = baseState();
  state.ball = { x: 180, y: 110, r: BALL_R, vx: -300, vy: 0 };
  state.bricks = [brick(100, 100)];
  step(state, 1 / 60); // ball edge now inside the right face
  frame(fakeCtx(), state);
  assert.ok(state.ball.vx > 0, 'vx must flip');
  assert.equal(state.ball.vy, 0, 'vy untouched by a side hit');
  assert.equal(state.ball.x, 100 + 72 + BALL_R, 'ball pushed right of the brick');
});

test('D4b: corner hit with equal penetration flips BOTH axes', () => {
  const state = baseState();
  state.ball = { x: 94, y: 94, r: BALL_R, vx: 50, vy: 50 }; // 1px into x and y
  state.bricks = [brick(100, 100)];
  frame(fakeCtx(), state);
  assert.ok(state.ball.vx < 0, 'vx must flip on a corner hit');
  assert.ok(state.ball.vy < 0, 'vy must flip on a corner hit');
  assert.equal(state.ball.x, 100 - BALL_R);
  assert.equal(state.ball.y, 100 - BALL_R);
});

// --- D5: sticky — overlap must be fully resolved ----------------------------
test('D5: deep overlap must be pushed fully out, not left in place', () => {
  const state = baseState();
  state.ball = { x: 136, y: 108, r: BALL_R, vx: 0, vy: 300 }; // 8px inside the top face
  state.bricks = [brick(100, 100)];
  frame(fakeCtx(), state);
  assert.ok(!collides(state.ball, state.bricks[0]), 'ball must be out of the brick');
  assert.equal(state.ball.y, 100 - BALL_R, 'pushed to just above the top face');
  assert.ok(state.ball.vy < 0, 'vy flipped');
});

// --- D6: paddle tunneling ---------------------------------------------------
test('D6: fast ball crossing the paddle in one step must still bounce', () => {
  const state = baseState();
  state.level = 7;
  state.ball = { x: 320, y: PADDLE_Y - BALL_R - 0.1, r: BALL_R, vx: 0, vy: ballSpeed(7) };
  step(state, 0.05); // 40px step: fully crosses the 12px window and the paddle
  assert.ok(state.ball.vy < 0, 'ball must bounce off the paddle');
  assert.equal(state.ball.y, PADDLE_Y - BALL_R);
});

// --- D7: paddle corner graze (center-based x test) ---------------------------
test('D7: ball grazing the paddle corner must bounce, not fall through', () => {
  const state = baseState();
  state.ball = { x: PADDLE_Y - 3, y: PADDLE_Y - BALL_R - 0.1, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  state.ball.x = state.paddle.x - 3; // center outside, edge overlapping
  step(state, 1 / 60);
  assert.ok(state.ball.vy < 0, 'corner graze must bounce');
});

// --- D8: angle mort — vx = 0 at the exact paddle center ----------------------
test('D8: dead-center paddle hit must not produce a pure vertical loop', () => {
  const state = baseState();
  state.ball = { x: state.paddle.x + state.paddle.w / 2, y: PADDLE_Y - BALL_R - 0.1, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, 1 / 60);
  assert.ok(Math.abs(state.ball.vx) >= 0.15 * ballSpeed(1), '|vx| must stay playable');
});

// --- D9: vitesse — paddle bounce must keep the level speed -------------------
test('D9: paddle bounce at hit=0.5 must keep |v| equal to the level speed', () => {
  const state = baseState();
  state.ball = { x: state.paddle.x + state.paddle.w / 2 + state.paddle.w / 4, y: PADDLE_Y - BALL_R - 0.1, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, 1 / 60);
  assert.ok(
    Math.abs(Math.hypot(state.ball.vx, state.ball.vy) - ballSpeed(1)) < 1e-6,
    `|v| must equal ${ballSpeed(1)}, got ${Math.hypot(state.ball.vx, state.ball.vy).toFixed(2)}`
  );
});

// --- D10: dt-independence -----------------------------------------------------
test('D10: same crossing at dt=0.05 and dt=1/120 must give the same outcome', () => {
  const run = (dt) => {
    const state = baseState();
    state.level = 6;
    state.ball = { x: 136, y: 127.1, r: BALL_R, vx: 0, vy: -ballSpeed(6) };
    state.bricks = [brick(100, 100)];
    step(state, dt);
    frame(fakeCtx(), state);
    return { alive: state.bricks[0].alive, vy: state.ball.vy };
  };
  const slow = run(0.05); // 35.5px step — tunnels on a positional test
  const fast = run(1 / 120); // 5.9px step — caught by a positional test
  assert.equal(slow.alive, false, 'dt=0.05 must break the brick too');
  assert.ok(slow.vy > 0, 'dt=0.05 must bounce');
  assert.equal(fast.alive, false, 'dt=1/120 must break the brick');
  assert.ok(fast.vy > 0, 'dt=1/120 must bounce');
});

