// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The face decision lives in resolveBricks().
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Resolves every brick the ball overlaps this pass: destroys the bricks,
// scores them, flips the velocity of the touched face and pushes the ball
// back out. Pure logic (no DOM), called from step() and testable directly.
// One rebound per axis per pass: a ball straddling the 8 px seam between two
// rows (gap < ball diameter) overlaps both and must bounce only once.
export function resolveBricks(state) {
  const { ball, bricks } = state;
  for (const brick of bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;

    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    // Naive first pass (D1): flip the axis of movement. Face selection and
    // push-out are layered in by the following tickets.
    if (Math.abs(ball.vx) > Math.abs(ball.vy)) ball.vx = -ball.vx;
    else ball.vy = -ball.vy;
  }
}

