test('D4a: side hit flips vx only and pushes the ball back to the entry side', () => {
  const state = createState(1);
  state.ball = { x: 180, y: 110, r: 7, vx: -300, vy: 0 };
  state.bricks = [{ x: 100, y: 100, w: 72, h: 20, row: 0, alive: true, points: 50 }];
  step(state, 1 / 60); // ball edge now inside the right face
  resolveBricks(state);
  assert.ok(state.ball.vx > 0, 'vx must flip');
  assert.equal(state.ball.vy, 0, 'vy untouched by a side hit');
  assert.equal(state.ball.x, 100 + 72 + 7, 'pushed right of the brick');
});

// --- D3: seam straddle (grid gap 8 px < ball diameter 14 px) ---------------
// A ball crossing a seam always overlaps the two neighbouring bricks at once;
// resolving them one by one would flip the axis twice and cancel the bounce.

test('D3a: ball straddling the 8px seam between two rows bounces exactly once', () => {
  const state = createState(1);
  state.ball = { x: 40, y: 72, r: 7, vx: 0, vy: 300 }; // centre in the seam band ]69, 75[
  state.bricks = [
    { x: 4, y: 48, w: 72, h: 20, row: 0, alive: true, points: 50 },
    { x: 4, y: 76, w: 72, h: 20, row: 1, alive: true, points: 40 },
  ];
  assert.equal(collides(state.ball, state.bricks[0]), true, 'straddles row 0');
  assert.equal(collides(state.ball, state.bricks[1]), true, 'straddles row 1');
  resolveBricks(state);
  assert.ok(state.ball.vy < 0, 'vy must flip exactly once (not twice)');
  assert.equal(state.ball.y, 48 - 7, 'ball pushed out above the seam');
  assert.ok(!collides(state.ball, state.bricks[0]), 'out of the upper brick');
  assert.ok(!collides(state.ball, state.bricks[1]), 'out of the lower brick');
  assert.equal(state.bricks[0].alive, false);
  assert.equal(state.bricks[1].alive, false);
});

test('D3b: ball on the 4-brick grid intersection bounces once per axis', () => {
  const state = createState(1);
  state.ball = { x: 80, y: 72, r: 7, vx: 100, vy: 300 }; // straddles both seams
  state.bricks = [
    { x: 4, y: 48, w: 72, h: 20, row: 0, alive: true, points: 50 },
    { x: 84, y: 48, w: 72, h: 20, row: 0, alive: true, points: 50 },
    { x: 4, y: 76, w: 72, h: 20, row: 1, alive: true, points: 40 },
    { x: 84, y: 76, w: 72, h: 20, row: 1, alive: true, points: 40 },
  ];
  for (const b of state.bricks) {
    assert.equal(collides(state.ball, b), true, 'straddles each of the four bricks');
  }
  resolveBricks(state);
  assert.ok(state.ball.vx < 0, 'vx must flip exactly once');
  assert.ok(state.ball.vy < 0, 'vy must flip exactly once');
  assert.equal(state.ball.x, 4 + 72 - 7, 'pushed left of the left column');
  assert.equal(state.ball.y, 48 - 7, 'pushed above the top row');
  assert.ok(state.bricks.every((b) => !b.alive), 'all four bricks destroyed');
  assert.ok(state.bricks.every((b) => !collides(state.ball, b)), 'out of every brick');
});

