```js
export function resolveBricks(state) {
  const { ball, bricks } = state;
  const EPS = 0.5;

  // A ball straddling a grid seam overlaps several bricks at once; resolve
  // the whole overlap set as one contact so the axis is flipped at most once
  // per pass (gap 8 px < ball diameter 14 px makes straddling unavoidable).
  for (let pass = 0; pass < 4; pass++) {
    const set = bricks.filter((b) => b.alive && collides(ball, b));
    if (set.length === 0) return;

    // Distance the ball must travel on each side to fully clear the set.
    let clearLeft = -Infinity;
    let clearRight = -Infinity;
    let clearUp = -Infinity;
    let clearDown = -Infinity;
    for (const b of set) {
      clearLeft = Math.max(clearLeft, ball.x + ball.r - (b.x + b.w));
      clearRight = Math.max(clearRight, b.x - (ball.x - ball.r));
      clearUp = Math.max(clearUp, ball.y + ball.r - b.y);
      clearDown = Math.max(clearDown, b.y + b.h - (ball.y - ball.r));
    }

    for (const b of set) {
      b.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(b, state.combo);
    }

    const dx = Math.min(clearLeft, clearRight);
    const dy = Math.min(clearUp, clearDown);

    // The axis that binds is the one the ball must actually cross; a
    // negative clearance means the ball is already clear on both sides.
    let axis; // 'x' | 'y'
    if (dx <= 0) axis = 'y';
    else if (dy <= 0) axis = 'x';
    else axis = dx <= dy ? 'x' : 'y';

    if (axis === 'x') {
      ball.vx = -ball.vx;
      if (ball.vx < 0) ball.x -= clearLeft;
      else if (ball.vx > 0) ball.x += clearRight;
      else if (clearLeft <= clearRight) ball.x -= clearLeft;
      else ball.x += clearRight;
    } else {
      ball.vy = -ball.vy;
      if (ball.vy < 0) ball.y -= clearUp;
      else if (ball.vy > 0) ball.y += clearDown;
      else if (clearUp <= clearDown) ball.y -= clearUp;
      else ball.y += clearDown;
    }
  }
}
```

