// Resolves every brick the ball overlaps this pass: destroys the bricks,
// scores them, flips the velocity of the touched face and pushes the ball
// back out. Pure logic (no DOM), called from step() and testable directly.
//
// The grid gap is 8 px while the ball measures 14 px: a ball crossing a seam
// therefore ALWAYS overlaps two bricks at once. The overlap set is resolved
// as a single contact (one rebound per axis per pass) and the axis is the one
// with the smallest clearance to a free position.
export function resolveBricks(state) {
  const { ball, bricks } = state;
  const EPS = 0.5;

  for (let pass = 0; pass < 4; pass++) {
    const set = bricks.filter((b) => b.alive && collides(ball, b));
    if (set.length === 0) return;

    // Distance the ball must travel on each side to fully clear the set.
    let minX = Infinity;
    let maxX = -Infinity;
    let minY = Infinity;
    let maxY = -Infinity;
    for (const b of set) {
      minX = Math.min(minX, b.x);
      maxX = Math.max(maxX, b.x + b.w);
      minY = Math.min(minY, b.y);
      maxY = Math.max(maxY, b.y + b.h);
    }
    const clearLeft = ball.x + ball.r - minX;
    const clearRight = maxX - (ball.x - ball.r);
    const clearUp = ball.y + ball.r - minY;
    const clearDown = maxY - (ball.y - ball.r);
    const dx = Math.min(clearLeft, clearRight);
    const dy = Math.min(clearUp, clearDown);

    for (const b of set) {
      b.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(b, state.combo);
    }

    // Corner: equal penetration on both axes -> flip both, push back on both.
    if (dx > 0 && dy > 0 && Math.abs(dx - dy) <= EPS) {
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
      if (ball.vx < 0) ball.x -= clearLeft;
      else if (ball.vx > 0) ball.x += clearRight;
      else if (clearLeft <= clearRight) ball.x -= clearLeft;
      else ball.x += clearRight;
      if (ball.vy < 0) ball.y -= clearUp;
      else if (ball.vy > 0) ball.y += clearDown;
      else if (clearUp <= clearDown) ball.y -= clearUp;
      else ball.y += clearDown;
      continue;
    }

    // The axis that binds: the one with the smallest clearance to a free
    // position. A non-positive clearance means the ball is already clear on
    // that axis, so the other one binds.
    let axisX;
    if (dx <= 0) axisX = false;
    else if (dy <= 0) axisX = true;
    else axisX = dx <= dy;

    if (axisX) {
      ball.vx = -ball.vx;
      if (ball.vx < 0) ball.x -= clearLeft;
      else if (ball.vx > 0) ball.x += clearRight;
      else if (clearLeft <= clearRight) ball.x -= clearLeft;
      else ball.x += clearRight;
    } else {
      ball.vy = -ball.vy;
      if (ball.vy < 0) ball.y -= clearUp;
      else if (ball.vy > 0) ball.y += clearDown;
      else if (clearUp <= clearDown) ball.y -= clearUp;
      else ball.y += clearDown;
    }
  }
}

