      maxX = Math.max(maxX, b.x + b.w);
      minY = Math.min(minY, b.y);
      maxY = Math.max(maxY, b.y + b.h);
    }
    const clearLeft = ball.x + ball.r - minX;
    const clearRight = maxX - (ball.x - ball.r);
    const clearUp = ball.y + ball.r - minY;
    const clearDown = maxY - (ball.y - ball.r);
    const dx = Math.min(clearLeft, clearRight);
    const dy = Math.min(clearUp, clearDown);

