export const BRICK_TOP = 48;

// A step is cut into substeps of at most this many pixels. The thinnest
// obstacle is the paddle window (12 px) and a brick band is 34 px wide: a
// substep shorter than both can never jump over either (no tunneling).
const MAX_SUBSTEP_PX = 12;

const STORAGE_KEY = 'neon.best';

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the ceiling, the paddle and the bricks. Movement is sub-stepped
// so a long frame (dt capped at 50 ms) can never jump over an obstacle.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const distance = Math.hypot(ball.vx, ball.vy) * dt;
  const substeps = Math.max(1, Math.ceil(distance / MAX_SUBSTEP_PX));
  const sdt = dt / substeps;

  for (let i = 0; i < substeps; i++) {
    ball.x += ball.vx * sdt;
    ball.y += ball.vy * sdt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
